#include <stdexcept>
#include <string>
int main(int argc, char **) {
  std::string text(static_cast<unsigned>(argc) + 40U, 'x');
  try { if (argc > 5) throw std::runtime_error(text); }
  catch (const std::exception &error) { return static_cast<int>(error.what()[0]); }
  return static_cast<int>(text.size() % 2U);
}

